 async function mapColumnToStandard(columnId:number){if(!selectedStandardId){setNotice('请先选择要映射的数据标准');return}try{const detail=await request('/standards/'+selectedStandardId);const version=detail.versions.find((v:any)=>v.version_number===detail.current_version);if(!version)throw new Error('该标准没有可用版本');await request('/standards/'+selectedStandardId+'/versions/'+version.id+'/mappings',{method:'POST',body:JSON.stringify({metadata_column_id:columnId,mapping_status:'待核验',note:''})});setMetadataDetail(await request('/metadata/tables/'+metadataDetail.id));setNotice('标准字段映射已保存')}catch(e:any){setNotice(e.message)}}
