 async function submitBulkStandardMapping(){try{if(!bulkMapStandard||!bulkMapTable||!bulkMapColumns.length)throw new Error('请选择标准、数据表及字段');const detail=await request('/standards/'+bulkMapStandard);const version=detail.versions.find((v:any)=>v.version_number===detail.current_version);if(!version)throw new Error('标准当前版本不可用');const mappings=bulkMapColumns.map(metadata_column_id=>({metadata_column_id,mapping_status:'待核验',note:'批量映射，待业务核验'}));const result=await request('/standards/'+bulkMapStandard+'/versions/'+version.id+'/mappings/bulk',{method:'POST',body:JSON.stringify({mappings})});setNotice('批量映射已提交：'+result.count+'个字段');setBulkMapColumns([]);setBulkMapOpen(false);setBulkMapTable(0);setMetadataDetail(null)}catch(e:any){setNotice(e.message)}}
