 async function publishStandard(row:DataStandard){try{const detail=await request('/standards/'+row.id);const current=detail.versions.find((v:any)=>v.version_number===detail.current_version);if(!current)throw new Error('当前版本不存在');await request('/standards/'+row.id+'/versions/'+current.id+'/publish',{method:'POST'});setNotice('标准版本已发布');await load()}catch(e:any){setNotice(e.message)}}
